// Lee la info del usuario que vino de get_info_usuario_db
const user = $('get_info_usuario_db').item.json;

let routeType;
let escalateToHuman = false;

// Clasificación por loan_status (ver imagen de totales)
if (!user.user_id) {
  // Cliente que no existe en la DB de FinDemo
  routeType = 'UNKNOWN_USER';

} else if (user.loan_status === 'DISBURSED' || user.loan_status === 'REFINANCE') {
  // Préstamo activo → va al warehouse por datos de cobranza
  routeType = 'ACTIVE_LOAN';

} else if (user.loan_status === 'PAID_OFF' || user.is_paid_off === 1) {
  // Ya pagó → va a producción por la oferta de renovación
  routeType = 'PAID_OFF';

} else if (user.loan_status === 'WAITING_FOR_DISBURSAL') {
  // Firmó contrato, esperando dispersión
  routeType = 'WAITING_DISBURSAL';

} else if (user.loan_status === 'FAILED_DISBURSAL') {
  // Dispersión falló → siempre escalar
  routeType = 'FAILED_DISBURSAL';
  escalateToHuman = true;

} else if (user.credit_check_status === 'REJECTED' || user.verification_status === 'REJECTED') {
  // Cliente rechazado → rama dedicada
  // El bot decide: respuesta automática de status vs ofrecer préstamo en garantía
  routeType = 'REJECTED';

} else if (user.application_type && !user.loan_status) {
  // Está en proceso de aplicación, aún no hay loan
  routeType = 'IN_APPLICATION';

} else {
  // Cualquier otro caso no contemplado
  routeType = 'OTHER';
}

// Contexto básico que siempre se pasa (útil para todas las ramas)
const baseContext = {
  user_id: user.user_id || null,
  first_name: user.first_name || null,
  full_name: [user.first_name, user.middle_name, user.last_name_1, user.last_name_2]
    .filter(Boolean).join(' ') || null,
  primary_email: user.primary_email || null,
  curp: user.curp || null,
  // Estado de la aplicación
  application_id: user.application_id || null,
  application_type: user.application_type || null,
  application_date: user.application_date || null,
  credit_check_status: user.credit_check_status || null,
  verification_status: user.verification_status || null,
  process_status: user.process_status || null,
  signature: user.signature !== null && user.signature !== undefined ? user.signature : null,
  // Estado del loan
  loan_id: user.loan_id || null,
  loan_status: user.loan_status || null,
  loan_number: user.loan_number || null,
  is_paid_off: user.is_paid_off || null,
  // Datos de dispersión
  disbursal_date: user.disbursal_date || null,
  disbursal_status: user.disbursal_status || null,
  cep_url: user.cep_url || null,
  // CLABE
  user_clabe: user.user_clabe || null,
  // Skip payments (básico, el detalle viene del warehouse en ACTIVE_LOAN)
  skip_payment_counter: user.skip_payment_counter || null,
  skip_payment_limit: user.skip_payment_limit || null
};

return [{
  json: {
    route_type: routeType,
    escalate_to_human: escalateToHuman,
    needs_daily_query: routeType === 'ACTIVE_LOAN',
    needs_offer_query: routeType === 'PAID_OFF',
    base_context: baseContext
  }
}];

